import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { trpc } from "@/lib/trpc";
import { can, powerRoleLabels, type PowerCapability, type PowerRole } from "@shared/powerhub-rbac";
import { AlertTriangle, BarChart3, Building2, CircleDollarSign, Database, Radio, Search, ShieldAlert, Ticket, UsersRound, WalletCards, Wrench } from "lucide-react";
import { FormEvent, useState } from "react";
import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { toast } from "sonner";

const inputClass = "h-10 w-full rounded-xl border border-white/10 bg-white/[.025] px-3 text-sm text-white outline-none placeholder:text-slate-600 focus:border-[#F5B800]/70";
const format = (value: unknown) => new Intl.NumberFormat("ar").format(Number(value ?? 0));
const date = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleDateString("ar-IQ", { year: "numeric", month: "short", day: "numeric" }) : "—";
const complaintStatus: Record<string, string> = { open: "مفتوحة", assigned: "مُسندة", in_progress: "قيد المعالجة", resolved: "محلولة", closed: "مغلقة" };

function Metric({ label, value, suffix = "", icon: Icon, tone = "gold" }: { label: string; value: unknown; suffix?: string; icon: typeof Building2; tone?: "gold" | "green" | "red" }) {
  const color = tone === "green" ? "text-emerald-400" : tone === "red" ? "text-rose-400" : "text-[#F5B800]";
  return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><Icon className={`h-5 w-5 ${color}`} /><p className="mt-5 text-sm text-slate-400">{label}</p><p className="mt-2 text-3xl font-extrabold text-white">{format(value)}{suffix}</p></CardContent></Card>;
}

const DASHBOARD_REFRESH_MS = 30_000;

export function AdvancedDashboard() {
  const dashboard = trpc.admin.advancedDashboard.useQuery(undefined, { refetchInterval: DASHBOARD_REFRESH_MS, refetchIntervalInBackground: true, staleTime: 10_000 });
  const [query, setQuery] = useState("");
  const search = trpc.admin.globalSearch.useQuery({ query }, { enabled: query.trim().length >= 2 });
  const data = dashboard.data;
  const collections = (data?.collectionsByGenerator ?? []) as Array<{ generatorName: string; code: string; amount: number }>;
  const top = collections.slice(0, 5);
  const low = [...collections].sort((a, b) => a.amount - b.amount).slice(0, 5);
  const collectionRate = Number(data?.kpis.collectionRate);
  return <section className="space-y-6">
    <Card className="border-[#F5B800]/15 bg-gradient-to-l from-[#111823] to-[#131d2b] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-sm font-bold text-[#F5B800]">لوحة التحكم الرئيسية</p><h2 className="mt-2 text-2xl font-extrabold text-white">متابعة تشغيل PowerHub من مركز واحد</h2><p className="mt-2 text-sm leading-7 text-slate-400">مؤشرات حية وتحليلات مركزية للمولدات والمشتركين والتحصيل والشكاوى.</p></div><div className="relative w-full lg:max-w-md"><Search className="absolute right-3 top-3 h-4 w-4 text-slate-500" /><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="بحث باسم مولد أو رقم اشتراك أو هاتف…" className={inputClass + " pr-9"} /><div className="absolute z-20 mt-2 w-full rounded-xl border border-white/10 bg-[#111823] shadow-xl">{query.length >= 2 && (search.data ?? []).map((result) => <div key={`${result.kind}-${result.id}`} className="border-b border-white/6 px-3 py-2 text-sm last:border-0"><p className="font-bold text-white">{result.label}</p><p className="mt-1 text-xs text-slate-500">{result.reference} · {result.tenantName}</p></div>)}{query.length >= 2 && !search.data?.length && <p className="p-3 text-sm text-slate-500">لا توجد نتائج مطابقة.</p>}</div></div></div></CardContent></Card>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="المولدات النشطة" value={data?.kpis.activeGenerators} icon={Building2} tone="green" /><Metric label="إجمالي المشتركين" value={data?.kpis.subscribers} icon={UsersRound} /><Metric label="استهلاك اليوم kWh" value={data?.kpis.dailyConsumption} icon={BarChart3} /><Metric label="تحصيل هذا الشهر" value={data?.kpis.monthlyCollections} icon={CircleDollarSign} tone="green" /><Metric label="شكاوى مفتوحة" value={data?.kpis.openComplaints} icon={Ticket} tone="red" /><Metric label="مولدات تحتاج مراجعة" value={data?.kpis.generatorsToReview} icon={Wrench} tone="red" /><Metric label="استهلاك الشهر kWh" value={data?.kpis.monthlyConsumption} icon={BarChart3} /><Metric label="نسبة التحصيل" value={Number.isFinite(collectionRate) ? collectionRate : 0} suffix="%" icon={CircleDollarSign} tone="green" /></div>
    <div className="grid gap-6 xl:grid-cols-2"><ChartCard title="نمو المشتركين خلال آخر 12 شهراً"><ResponsiveContainer width="100%" height={240}><LineChart data={data?.monthlyGrowth ?? []}><CartesianGrid stroke="#ffffff12" vertical={false} /><XAxis dataKey="month" stroke="#64748b" fontSize={11} /><YAxis stroke="#64748b" fontSize={11} /><Tooltip contentStyle={{ background: "#111823", border: "1px solid #ffffff1a", borderRadius: 12 }} /><Line type="monotone" dataKey="count" stroke="#F5B800" strokeWidth={3} dot={{ fill: "#F5B800" }} /></LineChart></ResponsiveContainer></ChartCard><ChartCard title="توزيع الاستهلاك حسب المناطق"><ResponsiveContainer width="100%" height={240}><BarChart data={data?.consumptionByRegion ?? []}><CartesianGrid stroke="#ffffff12" vertical={false} /><XAxis dataKey="region" stroke="#64748b" fontSize={11} /><YAxis stroke="#64748b" fontSize={11} /><Tooltip contentStyle={{ background: "#111823", border: "1px solid #ffffff1a", borderRadius: 12 }} /><Bar dataKey="consumptionKwh" fill="#2dd4bf" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></ChartCard></div>
    <div className="grid gap-6 xl:grid-cols-2"><ChartCard title="أعلى المولدات تحصيلاً"><GeneratorRank rows={top} color="#22c55e" /></ChartCard><ChartCard title="الأقل تحصيلاً"><GeneratorRank rows={low} color="#fb7185" /></ChartCard></div>
    <div className="grid gap-6 xl:grid-cols-3"><QuickList title="آخر المولدات المسجلة" rows={(data?.latestGenerators ?? []).map((item) => ({ title: item.name, detail: `${item.tenantName} · ${item.status}`, meta: item.code }))} /><QuickList title="الشكاوى الجديدة" rows={(data?.recentComplaints ?? []).map((item) => ({ title: item.title, detail: `${item.tenantName} · ${complaintStatus[item.status] ?? item.status}`, meta: item.priority }))} /><QuickList title="الاشتراكات الأقرب انتهاءً" rows={(data?.expiringSubscriptions ?? []).map((item) => ({ title: item.ownerName ?? item.tenantName, detail: item.tenantName, meta: date(item.endsAt) }))} /></div>
  </section>;
}

export function OperationalMonitoringPanel({ onNavigate }: { onNavigate: (target: "notifications" | "security" | "reports" | "field_sync") => void }) {
  const monitoring = trpc.admin.operationalMonitoring.useQuery(undefined, { refetchInterval: DASHBOARD_REFRESH_MS, refetchIntervalInBackground: true, staleTime: 10_000 });
  const data = monitoring.data;
  const iconByKey = { database: Database, messaging: Radio, sync: Wrench, security: ShieldAlert } as const;
  const tone = (state: string) => state === "healthy" ? "border-emerald-400/20 bg-emerald-400/[.055] text-emerald-200" : state === "warning" ? "border-amber-400/25 bg-amber-400/[.06] text-amber-100" : "border-rose-400/25 bg-rose-400/[.07] text-rose-100";
  const label = (state: string) => state === "healthy" ? "سليم" : state === "warning" ? "يحتاج متابعة" : "حرج";
  return <section className="grid gap-6 xl:grid-cols-[.95fr_1.35fr]"><Card className="border-sky-400/20 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">الصحة التشغيلية</h2><p className="mt-1 text-sm leading-6 text-slate-400">حالة لحظية مبنية على استجابة البيانات والرسائل والمزامنة والأمان.</p></div><Badge className="bg-sky-400/10 text-sky-200">تحديث تلقائي</Badge></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{monitoring.isLoading ? Array.from({ length: 4 }).map((_, index) => <div key={index} className="h-28 animate-pulse rounded-2xl border border-white/8 bg-white/[.025]" />) : (data?.health ?? []).map((item) => { const Icon = iconByKey[item.key as keyof typeof iconByKey] ?? ShieldAlert; return <button key={item.key} type="button" onClick={() => onNavigate(item.target)} className={`rounded-2xl border p-4 text-right transition hover:brightness-110 focus:outline-none focus:ring-2 focus:ring-[#F5B800]/60 ${tone(item.state)}`}><div className="flex items-center justify-between gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-black/15"><Icon className="h-4 w-4" /></span><Badge className="border border-current bg-transparent text-current">{label(item.state)}</Badge></div><p className="mt-4 font-bold">{item.label}</p><p className="mt-1 text-xs leading-5 opacity-80">{item.detail}</p></button>; })}</div></CardContent></Card><Card className="border-amber-400/20 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold text-white">التنبيهات الموحدة</h2><p className="mt-1 text-sm leading-6 text-slate-400">فشل الرسائل ومشكلات المزامنة والأحداث الأمنية المفتوحة، مرتبة حسب الأحدث والأولوية.</p></div><Badge className={(data?.alerts?.length ?? 0) ? "bg-amber-400/10 text-amber-200" : "bg-emerald-400/10 text-emerald-300"}>{data?.alerts?.length ?? 0} متابعة</Badge></div><div className="mt-5 max-h-88 space-y-3 overflow-y-auto pr-1">{monitoring.isLoading ? Array.from({ length: 3 }).map((_, index) => <div key={index} className="h-20 animate-pulse rounded-xl border border-white/8 bg-white/[.025]" />) : data?.alerts?.map((alert) => <button key={alert.id} type="button" onClick={() => onNavigate(alert.target)} className={`w-full rounded-xl border p-3 text-right transition hover:bg-white/[.035] ${alert.severity === "critical" ? "border-rose-400/25 bg-rose-400/[.045]" : "border-amber-400/20 bg-amber-400/[.035]"}`}><div className="flex items-start justify-between gap-3"><div><p className="font-bold text-white">{alert.title}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-slate-400">{alert.detail}</p>{alert.tenantName ? <p className="mt-1 text-[11px] text-slate-500">{alert.tenantName}</p> : null}</div><Badge className={alert.severity === "critical" ? "bg-rose-400/10 text-rose-200" : "bg-amber-400/10 text-amber-200"}>{alert.severity === "critical" ? "عاجل" : "متابعة"}</Badge></div></button>)}{!monitoring.isLoading && !data?.alerts?.length ? <div className="rounded-xl border border-dashed border-emerald-400/25 bg-emerald-400/[.035] p-8 text-center text-sm text-emerald-200">لا توجد تنبيهات تشغيلية مفتوحة حالياً.</div> : null}</div></CardContent></Card></section>;
}

function ChartCard({ title, children }: { title: string; children: React.ReactNode }) { return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h3 className="font-bold text-white">{title}</h3><div className="mt-5">{children}</div></CardContent></Card>; }
function GeneratorRank({ rows, color }: { rows: Array<{ generatorName: string; code: string; amount: number }>; color: string }) { return <ResponsiveContainer width="100%" height={240}><BarChart data={rows} layout="vertical"><CartesianGrid stroke="#ffffff12" horizontal={false} /><XAxis type="number" stroke="#64748b" fontSize={11} /><YAxis type="category" dataKey="generatorName" width={120} stroke="#94a3b8" fontSize={11} /><Tooltip contentStyle={{ background: "#111823", border: "1px solid #ffffff1a", borderRadius: 12 }} /><Bar dataKey="amount" fill={color} radius={[0, 6, 6, 0]} /></BarChart></ResponsiveContainer>; }
function QuickList({ title, rows }: { title: string; rows: Array<{ title: string; detail: string; meta: string }> }) { return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h3 className="font-bold text-white">{title}</h3><div className="mt-4 space-y-3">{rows.map((row, index) => <div key={`${row.title}-${index}`} className="rounded-xl border border-white/8 bg-white/[.02] p-3"><div className="flex items-center justify-between gap-3"><p className="font-bold text-sm text-white">{row.title}</p><Badge className="bg-white/5 text-slate-300">{row.meta}</Badge></div><p className="mt-1 text-xs text-slate-500">{row.detail}</p></div>)}{!rows.length && <p className="py-6 text-center text-sm text-slate-500">لا توجد بيانات حتى الآن.</p>}</div></CardContent></Card>; }

export function ComplaintsPanel() {
  const utils = trpc.useUtils();
  const complaints = trpc.admin.listComplaints.useQuery(undefined);
  const users = trpc.admin.userDirectory.useQuery({});
  const update = trpc.admin.updateComplaint.useMutation({ onSuccess: () => { void utils.admin.listComplaints.invalidate(); toast.success("تم تحديث الشكوى."); }, onError: (error) => toast.error(error.message) });
  return <section className="space-y-6"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex items-center justify-between"><div><h2 className="font-bold text-white">الشكاوى</h2><p className="mt-1 text-sm text-slate-500">تعيين الموظف وتغيير الحالة وتسجيل الرد ضمن سجل مركزي.</p></div><Badge className="bg-rose-400/10 text-rose-300">{format((complaints.data ?? []).filter((item) => ["open", "assigned", "in_progress"].includes(item.status)).length)} مفتوحة</Badge></div><div className="mt-5 space-y-4">{(complaints.data ?? []).map((complaint) => <form key={complaint.id} onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); update.mutate({ id: complaint.id, status: String(form.get("status")) as "open", assignedUserId: form.get("assignedUserId") ? Number(form.get("assignedUserId")) : null, response: String(form.get("response") || "") || undefined }); }} className="rounded-2xl border border-white/8 bg-white/[.02] p-4"><div className="flex flex-col justify-between gap-3 md:flex-row"><div><p className="font-bold text-white">{complaint.title}</p><p className="mt-1 text-sm text-slate-400">{complaint.tenantName} · {complaint.siteName} · {complaint.subscriberName ?? "بدون مشترك"}</p><p className="mt-2 text-sm text-slate-500">{complaint.description}</p></div><Badge className="h-fit bg-white/5 text-slate-300">{complaintStatus[complaint.status]}</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-3"><select name="assignedUserId" defaultValue={complaint.assignedUserId ?? ""} className={inputClass}><option value="">غير مسند</option>{(users.data ?? []).map((user) => <option key={user.id} value={user.id}>{user.name ?? user.email ?? `مستخدم #${user.id}`}</option>)}</select><select name="status" defaultValue={complaint.status} className={inputClass}><option value="open">مفتوحة</option><option value="assigned">مُسندة</option><option value="in_progress">قيد المعالجة</option><option value="resolved">محلولة</option><option value="closed">مغلقة</option></select><Button disabled={update.isPending} className="bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">حفظ المعالجة</Button></div><textarea name="response" defaultValue={complaint.response ?? ""} placeholder="رد الآدمن أو الموظف" className="mt-3 min-h-20 w-full rounded-xl border border-white/10 bg-[#0D1117]/40 p-3 text-sm text-white outline-none" /></form>)}{!complaints.data?.length && <p className="py-12 text-center text-slate-500">لا توجد شكاوى مسجلة بعد.</p>}</div></CardContent></Card></section>;
}

export function PlatformControlPanel() {
  const utils = trpc.useUtils();
  const policies = trpc.admin.listTariffPolicies.useQuery();
  const config = trpc.admin.platformConfiguration.useQuery();
  const owners = trpc.admin.listOwners.useQuery();
  const save = trpc.admin.savePlatformSetting.useMutation({ onSuccess: () => { void utils.admin.platformConfiguration.invalidate(); toast.success("تم حفظ إعداد المنصة."); }, onError: (error) => toast.error(error.message) });
  const tariff = trpc.admin.createTariffPolicy.useMutation({ onSuccess: () => { void utils.admin.listTariffPolicies.invalidate(); void utils.admin.platformConfiguration.invalidate(); toast.success("تم حفظ التسعيرة الرسمية."); }, onError: (error) => toast.error(error.message) });
  const recovery = trpc.admin.requestOwnerAccessRecovery.useMutation({ onSuccess: () => { void utils.admin.platformConfiguration.invalidate(); toast.success("تم تسجيل طلب استرداد الوصول؛ التسليم الخارجي مؤجل."); }, onError: (error) => toast.error(error.message) });
  const maintenance = (config.data?.settings ?? []).find((setting) => setting.settingKey === "maintenance_mode");
  const contactSetting = (config.data?.settings ?? []).find((setting) => setting.settingKey === "platform_contact");
  return <section className="grid gap-6 xl:grid-cols-2"><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">التسعيرة الرسمية</h2><p className="mt-1 text-sm text-slate-500">نطاق سعري مرجعي للكيلوواط/ساعة؛ لا يعدّل تعرفات المستأجرين القائمة تلقائياً.</p><form className="mt-5 space-y-3" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); tariff.mutate({ minimumPricePerKwh: Number(form.get("min")), maximumPricePerKwh: Number(form.get("max")), effectiveFrom: new Date(`${String(form.get("effective"))}T00:00:00`), notificationRequested: form.get("notify") === "on", notes: String(form.get("notes") || "") || undefined }); }}><div className="grid grid-cols-2 gap-3"><Input required name="min" type="number" min="0" step="0.01" placeholder="الحد الأدنى" className={inputClass} /><Input required name="max" type="number" min="0" step="0.01" placeholder="الحد الأعلى" className={inputClass} /></div><Input required name="effective" type="date" className={inputClass} /><label className="flex items-center gap-2 text-sm text-slate-400"><input name="notify" type="checkbox" className="accent-[#F5B800]" />إنشاء طلب إشعار محلي (الإرسال مؤجل)</label><textarea name="notes" placeholder="ملاحظات" className="min-h-20 w-full rounded-xl border border-white/10 bg-[#0D1117]/40 p-3 text-sm text-white" /><Button disabled={tariff.isPending} className="w-full bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">حفظ التسعيرة</Button></form><div className="mt-5 space-y-2">{(policies.data ?? []).map((policy) => <div className="rounded-xl border border-white/8 bg-white/[.02] p-3 text-sm" key={policy.id}><p className="font-bold text-white">{policy.minimumPricePerKwh} — {policy.maximumPricePerKwh} لكل kWh</p><p className="mt-1 text-xs text-slate-500">يسري {date(policy.effectiveFrom)} · {policy.notificationRequested ? "طلب إشعار مسجل" : "دون إشعار"}</p></div>)}</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">وضع صيانة المنصة</h2><p className="mt-1 text-sm text-slate-500">عند التفعيل، يمنع الخادم إجراءات المستأجرين مع بقاء آدمن PowerHub قادراً على الإدارة.</p><form className="mt-5 space-y-3" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); save.mutate({ settingKey: "maintenance_mode", isEnabled: form.get("enabled") === "on", message: String(form.get("message") || "") || undefined }); }}><label className="flex items-center gap-2 rounded-xl border border-white/8 bg-white/[.02] p-3 text-sm text-white"><input name="enabled" defaultChecked={maintenance?.isEnabled} type="checkbox" className="accent-[#F5B800]" />تفعيل وضع الصيانة</label><textarea name="message" defaultValue={maintenance?.message ?? "المنصة تحت الصيانة مؤقتاً. يرجى المحاولة لاحقاً."} className="min-h-24 w-full rounded-xl border border-white/10 bg-[#0D1117]/40 p-3 text-sm text-white" /><Button disabled={save.isPending} variant="outline" className="w-full border-[#F5B800]/40 text-[#F5B800] hover:bg-[#F5B800]/10 hover:text-[#F5B800]">حفظ حالة الصيانة</Button></form><div className="mt-6 border-t border-white/8 pt-5"><h3 className="font-bold text-white">إعدادات الصفحة العامة والميزات</h3><p className="mt-1 text-sm text-slate-500">يمكن لاحقاً حفظ مفاتيح مظهر الرابط والميزات في الإعدادات العامة دون تعديل القنوات الخارجية.</p></div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">استرداد وصول صاحب المولد</h2><p className="mt-1 text-sm leading-7 text-slate-500">PowerHub يستخدم OAuth، لذلك لا يعرض أو يغير كلمات مرور. ينشئ هذا الإجراء طلب دعوة/استرداد موثقاً فقط؛ تنفيذ التسليم الخارجي مؤجل.</p><div className="mt-5 space-y-3">{(owners.data ?? []).map((owner) => <div className="flex items-center justify-between gap-3 rounded-xl border border-white/8 bg-white/[.02] p-3" key={owner.tenant.id}><div><p className="font-bold text-white">{owner.owner?.fullName ?? owner.tenant.name}</p><p className="mt-1 text-xs text-slate-500">{owner.tenant.name}</p></div><Button disabled={recovery.isPending} size="sm" variant="outline" onClick={() => recovery.mutate({ tenantId: owner.tenant.id })} className="border-white/10 text-white hover:bg-white/5 hover:text-white">طلب استرداد</Button></div>)}</div><div className="mt-4 rounded-xl border border-dashed border-rose-400/30 bg-rose-400/5 p-3 text-xs leading-6 text-rose-200">انتحال جلسة صاحب المولد معطّل في هذه النسخة إلى حين اعتماد سياسة موافقة وتأكيد مستقل وسجل قانوني واضح.</div></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">طلبات الاسترداد الأخيرة</h2><div className="mt-4 space-y-3">{(config.data?.recoveries ?? []).map((item) => <div className="rounded-xl border border-white/8 bg-white/[.02] p-3" key={item.id}><p className="font-bold text-white">{item.ownerName ?? item.tenantName}</p><p className="mt-1 text-xs text-slate-500">{item.method} · {item.status} · {date(item.createdAt)}</p></div>)}{!config.data?.recoveries?.length && <p className="py-8 text-center text-sm text-slate-500">لا توجد طلبات استرداد بعد.</p>}</div><Card className="border-emerald-400/20 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">رقم التواصل عبر WhatsApp</h2><p className="mt-1 text-sm leading-7 text-slate-500">هذا الرقم هو وجهة أزرار الالتحاق بالمنصة في الصفحة العامة: «سجل متجرك»، «أنشئ مساحتك» و«تواصل مع المنصة» وجميع أزرار الباقات.</p><form className="mt-5 space-y-3" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form=new FormData(event.currentTarget); const number=String(form.get("whatsappNumber")||"").trim(); save.mutate({ settingKey:"platform_contact", isEnabled:Boolean(number), value:{ whatsappNumber:number }, message:"رقم التواصل الرسمي للالتحاق بالمنصة عبر WhatsApp." }); }}><Input name="whatsappNumber" defaultValue={String((contactSetting?.value as any)?.whatsappNumber ?? "")} placeholder="+970..." dir="ltr" className={inputClass} aria-label="رقم WhatsApp الرسمي" /><p className="text-xs text-slate-500">اكتب الرقم بالصيغة الدولية، وسيُحوّل تلقائياً إلى رابط WhatsApp آمن.</p><Button disabled={save.isPending} className="w-full bg-emerald-400 font-bold text-[#0D1117] hover:bg-emerald-300">حفظ رقم التواصل</Button></form></CardContent></Card></CardContent></Card></section>;
}

export function GeneratorInspector({ rows }: { rows: Array<{ id: number; name: string; code: string; tenantName: string }> }) {
  const [generatorId, setGeneratorId] = useState<number | undefined>(rows[0]?.id);
  const details = trpc.admin.generatorDetails.useQuery({ generatorId: generatorId ?? 0 }, { enabled: Boolean(generatorId) });
  const data = details.data;
  return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><h2 className="font-bold text-white">تفاصيل مولد</h2><p className="mt-1 text-sm text-slate-500">الحالة الحية والمشتركون وآخر الفواتير وسجل النشاط.</p></div><select value={generatorId ?? ""} onChange={(event) => setGeneratorId(Number(event.target.value))} className={inputClass + " lg:max-w-sm"}>{rows.map((row) => <option key={row.id} value={row.id}>{row.name} · {row.code} · {row.tenantName}</option>)}</select></div>{data && <div className="mt-6 space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Metric label="القدرة kW" value={data.generator.ratedCapacityKw} icon={Building2} /><Metric label="ساعات التشغيل" value={data.generator.operatingHours} icon={Wrench} /><Metric label="مستوى الوقود" value={data.generator.fuelLevelLiters} icon={BarChart3} /><Metric label="إجمالي المشتركين" value={data.subscriberSummary.total} icon={UsersRound} /><Metric label="مشتركون نشطون" value={data.subscriberSummary.active} icon={UsersRound} tone="green" /></div><div className="rounded-xl border border-white/8 bg-white/[.02] p-4"><div className="flex flex-wrap items-center gap-3"><Badge className={data.generator.status === "active" ? "bg-emerald-400/10 text-emerald-300" : "bg-rose-400/10 text-rose-300"}>{data.generator.status}</Badge><span className="text-sm text-slate-400">{data.generator.tenantName} · {data.generator.siteName} · آخر صيانة: {date(data.generator.lastMaintenanceAt)}</span></div></div><div className="grid gap-6 xl:grid-cols-2"><DetailTable title="المشتركون المرتبطون" headers={["الاسم", "رقم الاشتراك", "النوع", "الحالة"]} rows={data.subscribers.map((row: (typeof data.subscribers)[number]) => [row.fullName, row.subscriberNo, row.subscriptionType === "commercial" ? "تجاري" : "سكني", row.serviceStatus])} empty="لا يوجد مشتركون مرتبطون بالمولد." /><DetailTable title="آخر الفواتير" headers={["الفاتورة", "المشترك", "الإجمالي", "الحالة"]} rows={data.invoices.map((row: (typeof data.invoices)[number]) => [row.invoiceNo, row.subscriberName, format(row.totalAmount), row.status])} empty="لا توجد فواتير مرتبطة بالمولد." /></div><DetailTable title="سجل النشاط" headers={["العملية", "الكيان", "المستخدم", "التاريخ"]} rows={data.activity.map((row: (typeof data.activity)[number]) => [row.action, row.entityType, row.userName ?? "النظام", date(row.createdAt)])} empty="لا يوجد نشاط مسجل بعد." /></div>}{!data && <p className="py-10 text-center text-sm text-slate-500">اختر مولداً لعرض تفاصيله.</p>}</CardContent></Card>;
}
function DetailTable({ title, headers, rows, empty }: { title: string; headers: string[]; rows: string[][]; empty: string }) { return <Card className="border-white/8 bg-[#0D1117]/35"><CardContent className="p-4"><h3 className="font-bold text-white">{title}</h3><div className="mt-4 max-h-64 overflow-auto"><table className="w-full min-w-[480px] text-right text-sm"><thead className="text-xs text-slate-500"><tr>{headers.map((header) => <th className="pb-3" key={header}>{header}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr className="border-t border-white/7" key={index}>{row.map((cell, cellIndex) => <td className="py-3 text-slate-300" key={cellIndex}>{cell}</td>)}</tr>)}{!rows.length && <tr><td colSpan={headers.length} className="py-8 text-center text-slate-500">{empty}</td></tr>}</tbody></table></div></CardContent></Card>; }

export function GeneratorDirectorySearch({ rows }: { rows: Array<{ id: number; name: string; code: string; status: string; ratedCapacityKw: string | null; tenantName: string; siteName: string }> }) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("all");
  const filtered = rows.filter((row) => (status === "all" || row.status === status) && `${row.name} ${row.code} ${row.tenantName} ${row.siteName}`.toLowerCase().includes(query.toLowerCase()));
  return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><h2 className="font-bold text-white">بحث وفلترة المولدات</h2><p className="mt-1 text-sm text-slate-500">اعثر على أي مولد بالاسم أو الرمز أو المحطة، ثم صفِّ النتائج بحالة التشغيل.</p></div><div className="grid w-full gap-3 sm:grid-cols-2 md:max-w-xl"><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="اسم المولد أو الرمز أو المحطة" className={inputClass} /><select value={status} onChange={(event) => setStatus(event.target.value)} className={inputClass}><option value="all">كل الحالات</option><option value="active">نشط</option><option value="maintenance">قيد الصيانة</option><option value="stopped">موقوف</option><option value="offline">غير متصل</option><option value="blocked">محظور</option></select></div></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[720px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">المولد</th><th className="pb-3">المالك / المحطة</th><th className="pb-3">القدرة</th><th className="pb-3">الحالة</th></tr></thead><tbody>{filtered.map((row) => <tr className="border-t border-white/7" key={row.id}><td className="py-3 font-bold text-white">{row.name}<span className="mr-2 text-xs font-normal text-slate-500">{row.code}</span></td><td className="py-3 text-slate-300">{row.tenantName} · {row.siteName}</td><td className="py-3 text-slate-300">{row.ratedCapacityKw == null ? "غير محددة" : `${row.ratedCapacityKw} kW`}</td><td className="py-3"><Badge className="bg-white/5 text-slate-300">{row.status}</Badge></td></tr>)}{!filtered.length && <tr><td colSpan={4} className="py-8 text-center text-slate-500">لا توجد مولدات مطابقة.</td></tr>}</tbody></table></div></CardContent></Card>;
}

export function OwnerLifecyclePanel() {
  const utils = trpc.useUtils();
  const owners = trpc.admin.listOwners.useQuery();
  const setStatus = trpc.admin.setTenantStatus.useMutation({ onSuccess: () => { void utils.admin.listOwners.invalidate(); void utils.admin.overview.invalidate(); toast.success("تم تحديث حالة مساحة صاحب المولد."); }, onError: (error) => toast.error(error.message) });
  return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div><h2 className="font-bold text-white">أصحاب المولدات وحالة الحساب</h2><p className="mt-1 text-sm text-slate-500">مراجعة التفعيل وآخر دخول وإيقاف المساحة أو إعادة تفعيلها مع حفظ سجل تدقيق.</p></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[760px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">صاحب المولد</th><th className="pb-3">المساحة</th><th className="pb-3">آخر دخول</th><th className="pb-3">الحالة</th><th className="pb-3">إجراء</th></tr></thead><tbody>{(owners.data ?? []).map((row) => <tr className="border-t border-white/7" key={row.tenant.id}><td className="py-4"><p className="font-bold text-white">{row.owner?.fullName ?? "غير مربوط"}</p><p className="mt-1 text-xs text-slate-500">{row.ownerAccount?.email ?? row.owner?.phone ?? "—"}</p></td><td className="py-4 text-slate-300">{row.tenant.name}</td><td className="py-4 text-slate-400">{date(row.ownerAccount?.lastSignedIn)}</td><td className="py-4"><Badge className={row.tenant.status === "active" ? "bg-emerald-400/10 text-emerald-300" : "bg-rose-400/10 text-rose-300"}>{row.tenant.status === "active" ? "فعّالة" : "موقوفة"}</Badge></td><td className="py-4"><Button disabled={setStatus.isPending} size="sm" variant="outline" onClick={() => setStatus.mutate({ tenantId: row.tenant.id, status: row.tenant.status === "active" ? "suspended" : "active" })} className={row.tenant.status === "active" ? "border-rose-400/30 text-rose-300 hover:bg-rose-400/10 hover:text-rose-200" : "border-emerald-400/30 text-emerald-300 hover:bg-emerald-400/10 hover:text-emerald-200"}>{row.tenant.status === "active" ? "إيقاف الحساب" : "إعادة التفعيل"}</Button></td></tr>)}{!owners.data?.length && <tr><td colSpan={5} className="py-8 text-center text-slate-500">لا يوجد أصحاب مولدات مسجلون.</td></tr>}</tbody></table></div></CardContent></Card>;
}

export function GeneralPlatformSettingsPanel() {
  const utils = trpc.useUtils();
  const configuration = trpc.admin.platformConfiguration.useQuery();
  const save = trpc.admin.savePlatformSetting.useMutation({ onSuccess: () => { void utils.admin.platformConfiguration.invalidate(); toast.success("تم حفظ الإعدادات العامة."); }, onError: (error) => toast.error(error.message) });
  const publicOptions = configuration.data?.settings.find((setting) => setting.settingKey === "public_invoice_options");
  const featureFlags = configuration.data?.settings.find((setting) => setting.settingKey === "platform_feature_flags");
  const publicValue = (publicOptions?.value ?? {}) as Record<string, unknown>;
  const featuresValue = (featureFlags?.value ?? {}) as Record<string, unknown>;
  return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">إعدادات الصفحة العامة والميزات</h2><p className="mt-1 text-sm leading-7 text-slate-500">تتحكم هذه الخيارات بالعرض العام لروابط المشتركين وبالميزات المحلية المسموح بها، ولا تعدّل بيانات أي مستأجر.</p><form className="mt-5 grid gap-6 xl:grid-cols-2" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); save.mutate({ settingKey: "public_invoice_options", isEnabled: form.get("publicEnabled") === "on", message: String(form.get("publicMessage") || "") || undefined, value: { showPlatformBranding: form.get("showPlatformBranding") === "on", showSupportText: form.get("showSupportText") === "on" } }); save.mutate({ settingKey: "platform_feature_flags", isEnabled: true, value: { meterPhoto: form.get("meterPhoto") === "on", offlineReadings: form.get("offlineReadings") === "on", publicInvoices: form.get("publicInvoices") === "on" } }); }}><div className="rounded-2xl border border-white/8 bg-white/[.02] p-4"><h3 className="font-bold text-white">رابط الفاتورة العامة</h3><label className="mt-4 flex items-center gap-2 text-sm text-slate-300"><input defaultChecked={publicOptions?.isEnabled} name="publicEnabled" type="checkbox" className="accent-[#F5B800]" />إتاحة مظهر الرابط العام</label><label className="mt-3 flex items-center gap-2 text-sm text-slate-300"><input defaultChecked={Boolean(publicValue.showPlatformBranding)} name="showPlatformBranding" type="checkbox" className="accent-[#F5B800]" />إظهار هوية PowerHub</label><label className="mt-3 flex items-center gap-2 text-sm text-slate-300"><input defaultChecked={Boolean(publicValue.showSupportText)} name="showSupportText" type="checkbox" className="accent-[#F5B800]" />إظهار نص الدعم</label><Input name="publicMessage" defaultValue={publicOptions?.message ?? ""} placeholder="رسالة تظهر في الرابط العام" className={inputClass + " mt-4"} /></div><div className="rounded-2xl border border-white/8 bg-white/[.02] p-4"><h3 className="font-bold text-white">ميزات المنصة</h3><label className="mt-4 flex items-center gap-2 text-sm text-slate-300"><input defaultChecked={featuresValue.meterPhoto !== false} name="meterPhoto" type="checkbox" className="accent-[#F5B800]" />رفع صورة العداد</label><label className="mt-3 flex items-center gap-2 text-sm text-slate-300"><input defaultChecked={featuresValue.offlineReadings !== false} name="offlineReadings" type="checkbox" className="accent-[#F5B800]" />القراءات دون اتصال</label><label className="mt-3 flex items-center gap-2 text-sm text-slate-300"><input defaultChecked={featuresValue.publicInvoices !== false} name="publicInvoices" type="checkbox" className="accent-[#F5B800]" />روابط الفواتير العامة</label><Button disabled={save.isPending} className="mt-5 w-full bg-[#F5B800] text-[#0D1117] hover:bg-[#ffd23f]">حفظ الإعدادات العامة</Button></div></form></CardContent></Card>;
}

export function BranchFeaturePolicyPanel() {
  const utils = trpc.useUtils();
  const configuration = trpc.admin.platformConfiguration.useQuery();
  const tenantSettings = trpc.admin.listTenantBranchSettings.useQuery();
  const saveFeature = trpc.admin.savePlatformSetting.useMutation({ onSuccess: () => { void utils.admin.platformConfiguration.invalidate(); void utils.admin.listTenantBranchSettings.invalidate(); toast.success("تم حفظ سياسة الأفرع."); }, onError: (error) => toast.error(error.message) });
  const saveTenant = trpc.admin.saveTenantBranchSettings.useMutation({ onSuccess: () => { void utils.admin.listTenantBranchSettings.invalidate(); toast.success("تم تحديث إعدادات الأفرع لصاحب المولد."); }, onError: (error) => toast.error(error.message) });
  const feature = configuration.data?.settings.find((item) => item.settingKey === "branch_feature");
  const featureValue = feature?.value && typeof feature.value === "object" && !Array.isArray(feature.value) ? feature.value as Record<string, unknown> : {};
  const storedLimits = featureValue.defaultLimit && typeof featureValue.defaultLimit === "object" && !Array.isArray(featureValue.defaultLimit) ? featureValue.defaultLimit as Record<string, unknown> : {};
  const limit = (packageCode: "basic" | "advanced" | "professional" | "business" | "vip", fallback: number) => typeof storedLimits[packageCode] === "number" || typeof storedLimits[packageCode] === "string" ? Number(storedLimits[packageCode]) : fallback;
  const planLimits = { basic: limit("basic", 1), advanced: limit("advanced", 1), professional: limit("professional", 1), business: limit("business", 1), vip: limit("vip", 2) };
  return <section className="space-y-6"><Card className="border-[#F5B800]/25 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 className="font-bold text-white">ميزة الأفرع متعددة المواقع</h2><p className="mt-1 max-w-3xl text-sm leading-7 text-slate-400">الأفرع نطاقات تشغيل مستقلة داخل حساب صاحب المولد. يُعزل المشتركون والعدادات والفواتير والموظفون بحسب الفرع، بينما يرى المالك الملخص المجمّع.</p></div><Badge className={feature?.isEnabled ? "w-fit bg-emerald-400/10 text-emerald-300" : "w-fit bg-amber-400/10 text-amber-300"}>{feature?.isEnabled ? "الميزة مفعلة على المنصة" : "الميزة متوقفة على المنصة"}</Badge></div><form className="mt-5 grid gap-4 md:grid-cols-3" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); saveFeature.mutate({ settingKey: "branch_feature", isEnabled: form.get("enabled") === "on", message: "إدارة الأفرع المتعددة لصاحب المولد", value: { defaultLimit: { basic: Number(form.get("basic")), advanced: Number(form.get("advanced")), professional: Number(form.get("professional")), business: Number(form.get("business")), vip: Number(form.get("vip")) } } }); }}><label className="md:col-span-3 flex items-center justify-between gap-4 rounded-2xl border border-[#F5B800]/25 bg-[#F5B800]/[.05] p-4 text-sm text-white"><span><strong className="block">تفعيل ميزة الأفرع</strong><span className="mt-1 block text-xs leading-6 text-slate-400">عند الإيقاف لا يمكن إنشاء أفرع جديدة، ويطبّق سلوك الحساب الذي تحدده لكل مستأجر على الأفرع القائمة.</span></span><input defaultChecked={feature?.isEnabled ?? false} name="enabled" type="checkbox" className="h-4 w-4 accent-[#F5B800]" /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">الناشئة</span><Input required min="1" max="1000" name="basic" type="number" defaultValue={planLimits.basic} className={inputClass} /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">النمو</span><Input required min="1" max="1000" name="advanced" type="number" defaultValue={planLimits.advanced} className={inputClass} /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">الاحتراف</span><Input required min="1" max="1000" name="professional" type="number" defaultValue={planLimits.professional} className={inputClass} /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">الأعمال</span><Input required min="1" max="1000" name="business" type="number" defaultValue={planLimits.business} className={inputClass} /></label><label className="block"><span className="mb-2 block text-xs font-bold text-slate-400">الذهبية - VIP</span><Input required min="1" max="1000" name="vip" type="number" defaultValue={planLimits.vip} className={inputClass} /></label><Button disabled={saveFeature.isPending} className="md:col-span-3 bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]">حفظ سياسة الأفرع وحدود الباقات</Button></form></CardContent></Card><Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-white">التفعيل والحد اليدوي لكل صاحب مولد</h2><p className="mt-1 text-sm leading-7 text-slate-500">يمكنك توريث سياسة الباقة أو تفعيل الميزة أو إيقافها يدوياً وتحديد حد مختلف للأفرع.</p></div><Badge className="w-fit bg-white/5 text-slate-300">{format(tenantSettings.data?.length)} حساباً</Badge></div><div className="mt-5 space-y-3">{(tenantSettings.data ?? []).map((tenant) => { const inheritedLimit = planLimits[tenant.packageCode as keyof typeof planLimits]; const effectiveLimit = tenant.maxBranchesOverride ?? inheritedLimit; const effectiveEnabled = tenant.isEnabledOverride ?? Boolean(feature?.isEnabled && inheritedLimit > 1); return <form key={tenant.tenantId} className="grid gap-3 rounded-2xl border border-white/8 bg-white/[.02] p-4 lg:grid-cols-[1.5fr_.9fr_.8fr_.8fr_auto] lg:items-end" onSubmit={(event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const state = String(form.get("enabledState")); const max = String(form.get("maxBranches") || "").trim(); saveTenant.mutate({ tenantId: tenant.tenantId, isEnabledOverride: state === "inherit" ? null : state === "enabled", maxBranchesOverride: max ? Number(max) : null, disabledBehavior: String(form.get("disabledBehavior")) as "read_only" | "suspended" }); }}><div><p className="font-bold text-white">{tenant.ownerName ?? tenant.tenantName}</p><p className="mt-1 text-xs text-slate-500">{tenant.tenantName} · {tenant.packageCode} · {tenant.currentBranchCount} / {effectiveLimit} فرع</p></div><label><span className="mb-1 block text-xs text-slate-500">التفعيل</span><select name="enabledState" defaultValue={tenant.isEnabledOverride === null ? "inherit" : tenant.isEnabledOverride ? "enabled" : "disabled"} className={inputClass}><option value="inherit">توريث الباقة</option><option value="enabled">مفعّل يدوياً</option><option value="disabled">متوقف يدوياً</option></select></label><label><span className="mb-1 block text-xs text-slate-500">الحد اليدوي</span><Input name="maxBranches" type="number" min="1" max="1000" placeholder={`الباقة: ${inheritedLimit}`} defaultValue={tenant.maxBranchesOverride ?? ""} className={inputClass} /></label><label><span className="mb-1 block text-xs text-slate-500">عند الإيقاف</span><select name="disabledBehavior" defaultValue={tenant.disabledBehavior ?? "read_only"} className={inputClass}><option value="read_only">قراءة فقط</option><option value="suspended">تجميد</option></select></label><Button disabled={saveTenant.isPending} size="sm" className="bg-white/8 text-white hover:bg-white/12">حفظ</Button><p className="lg:col-span-5 text-xs text-slate-500">الحالة الفعلية: <span className={effectiveEnabled ? "font-bold text-emerald-300" : "font-bold text-amber-300"}>{effectiveEnabled ? "مفعّل" : "متوقف"}</span>{tenant.maxBranchesOverride ? " · حد يدوي مطبق" : " · حد الباقة مطبق"}</p></form>; })}{!tenantSettings.data?.length && <p className="py-10 text-center text-sm text-slate-500">لا توجد حسابات أصحاب مولدات بعد.</p>}</div></CardContent></Card></section>;
}

