export function OwnerUsageReportPanel() {
  const report = trpc.admin.ownerQuotaUsageReport.useQuery(undefined, { staleTime: 15000 });
  const rows = report.data ?? [];
  const cell = (used:number, limit:number) => { const pct=limit>0?Math.min(100,Math.round(used/limit*100)):0; return {used,limit,pct}; };
  return <Card className="border-sky-400/20 bg-[#111823] shadow-panel"><CardContent className="p-5">
    <div><h2 className="font-bold text-white">تقرير استهلاك باقات أصحاب المولدات</h2><p className="mt-1 text-sm leading-7 text-slate-400">يعتمد على الحدود الفعلية الناتجة من الباقة والإضافات والاستثناءات، ويعرض المشتركين والأفرع والرسائل ومستخدمي المنصة والتطبيق الميداني.</p></div>
    <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[1500px] text-right text-sm"><thead className="text-xs text-slate-500"><tr><th className="pb-3">صاحب المولد</th><th className="pb-3">الباقة</th><th className="pb-3">المشتركون</th><th className="pb-3">الأفرع</th><th className="pb-3">الرسائل</th><th className="pb-3">مستخدمو المنصة</th><th className="pb-3">التطبيق الميداني</th><th className="pb-3">المضافات</th><th className="pb-3">المتبقي</th></tr></thead>
    <tbody>{rows.map((row:any)=>{const s=cell(row.usage.subscribers,row.limits.subscribers),b=cell(row.usage.branches,row.limits.branches),m=cell(row.messages.used,row.limits.messages),p=cell(row.usage.platformUsers,row.limits.platformUsers),f=cell(row.usage.fieldUsers,row.limits.fieldUsers);const worst=Math.max(s.pct,b.pct,m.pct,p.pct,f.pct);const tone=worst>=100?"bg-rose-400/10 text-rose-300":worst>=80?"bg-amber-400/10 text-amber-200":"bg-emerald-400/10 text-emerald-300";const addonText=row.addons.length?row.addons.map((a:any)=>"+"+a.quantity+" "+a.code).join("، "):"لا توجد";return <tr key={row.tenant.id} className="border-t border-white/7"><td className="py-3"><p className="font-bold text-white">{row.owner?.fullName??row.tenant.name}</p><p className="mt-1 text-xs text-slate-500">{row.tenant.name}</p></td><td className="py-3 text-slate-300">{row.package?.name??row.subscription?.packageCode??"—"}</td>{[s,b,m,p,f].map((x:any,i:number)=><td key={i} className="py-3 text-slate-300">{x.used} / {x.limit} <span className="text-xs text-slate-500">{x.pct}%</span></td>)}<td className="py-3 text-xs text-slate-400">{addonText}</td><td className="py-3"><Badge className={tone}>{worst>=100?"بلغ الحد":worst>=80?"قريب من الحد":"ضمن الحد"}</Badge><p className="mt-1 text-xs text-slate-500">{row.daysRemaining==null?"—":"متبقٍ "+row.daysRemaining+" يوم"}</p></td></tr>})}{!rows.length&&<tr><td colSpan={9} className="py-10 text-center text-slate-500">{report.isLoading?"جارٍ تحميل التقرير…":"لا توجد بيانات أصحاب مولدات لعرضها."}</td></tr>}</tbody></table></div>
  </CardContent></Card>;
}

export function OwnerUsagePriorityFiltersPanel() {
  const owners = trpc.admin.listOwners.useQuery();
  const branches = trpc.admin.listTenantBranchSettings.useQuery();
  const sms = trpc.admin.listTweetSmsAccounts.useQuery();
  const configuration = trpc.admin.platformConfiguration.useQuery();
  const [filter, setFilter] = useState<"all" | "near" | "reached" | "within">("all");
  const [sort, setSort] = useState<"priority" | "subscribers" | "branches" | "sms">("priority");
  const settingValue = (key: string) => { const setting = configuration.data?.settings.find((item) => item.settingKey === key); return setting?.value && typeof setting.value === "object" && !Array.isArray(setting.value) ? setting.value as Record<string, unknown> : {}; };
  const planSubscriberLimits = (settingValue("owner_subscriber_limits").limits ?? {}) as Record<string, unknown>;
  const planBranchLimits = (settingValue("branch_feature").defaultLimit ?? {}) as Record<string, unknown>;
  const overrides = (settingValue("owner_limit_overrides").overrides ?? {}) as Record<string, Record<string, unknown>>;
  const branchByTenant = new Map((branches.data ?? []).map((item: any) => [item.tenantId, item]));
  const smsByTenant = new Map((sms.data ?? []).map((item: any) => [item.tenantId, item]));
  const rows = (owners.data ?? []).map((owner: any) => { const plan = owner.subscription?.packageCode; const override = overrides[String(owner.tenant.id)] ?? {}; const branch = branchByTenant.get(owner.tenant.id); const smsAccount = smsByTenant.get(owner.tenant.id); const subscriberLimit = Number(typeof override.subscriberLimit === "number" ? override.subscriberLimit : planSubscriberLimits[plan] ?? ({ basic: 150, advanced: 300, professional: 500, business: 750, vip: 900 } as Record<string, number>)[plan] ?? 0); const branchLimit = Number(branch?.maxBranchesOverride ?? planBranchLimits[plan] ?? ({ basic: 1, advanced: 1, professional: 1, business: 1, vip: 2 } as Record<string, number>)[plan] ?? 0); const subscriber = subscriberLimit ? Math.min(100, Math.round(Number(owner.subscribers?.total ?? 0) / subscriberLimit * 100)) : 0; const branchPercent = branchLimit ? Math.min(100, Math.round(Number(branch?.currentBranchCount ?? 0) / branchLimit * 100)) : 0; const smsPercent = Number(smsAccount?.monthlyLimit ?? 0) ? Math.min(100, Math.round(Number(smsAccount?.usedThisMonth ?? 0) / Number(smsAccount.monthlyLimit) * 100)) : 0; return { id: owner.tenant.id, name: owner.owner?.fullName ?? owner.tenant.name, plan, subscriber, branch: branchPercent, sms: smsPercent, priority: Math.max(subscriber, branchPercent, smsPercent) }; });
  const visible = rows.filter((row) => filter === "all" || filter === "reached" ? filter !== "reached" || row.priority >= 100 : filter === "near" ? row.priority >= 80 && row.priority < 100 : row.priority < 80).sort((a, b) => sort === "subscribers" ? b.subscriber - a.subscriber : sort === "branches" ? b.branch - a.branch : sort === "sms" ? b.sms - a.sms : b.priority - a.priority);
  return <Card className="border-amber-400/20 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between"><div><h2 className="font-bold text-white">تصفية أولويات استهلاك الباقات</h2><p className="mt-1 text-sm text-slate-400">يُرتّب المتجاوزون 80% أولاً افتراضياً، ويمكن عزلهم أو الفرز حسب كل حد.</p></div><div className="grid gap-2 sm:grid-cols-2"><select aria-label="تصفية حالة استهلاك الباقات" value={filter} onChange={(event) => setFilter(event.target.value as typeof filter)} className={inputClass}><option value="all">كل أصحاب المولدات</option><option value="near">قريب من الحد (80%–99%)</option><option value="reached">بلغ الحد (100%)</option><option value="within">ضمن الحد (أقل من 80%)</option></select><select aria-label="ترتيب تقرير استهلاك الباقات" value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} className={inputClass}><option value="priority">الأولوية الأعلى أولاً</option><option value="subscribers">استهلاك المشتركين</option><option value="branches">استهلاك الأفرع</option><option value="sms">استهلاك SMS</option></select></div></div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{visible.map((row) => <div key={row.id} className={`rounded-2xl border p-4 ${row.priority >= 100 ? "border-rose-400/25 bg-rose-400/[.05]" : row.priority >= 80 ? "border-amber-400/25 bg-amber-400/[.05]" : "border-white/8 bg-white/[.02]"}`}><div className="flex items-start justify-between gap-3"><div><p className="font-bold text-white">{row.name}</p><p className="mt-1 text-xs text-slate-500">باقة {row.plan}</p></div><Badge className={row.priority >= 100 ? "bg-rose-400/10 text-rose-300" : row.priority >= 80 ? "bg-amber-400/10 text-amber-200" : "bg-emerald-400/10 text-emerald-300"}>{row.priority}%</Badge></div><div className="mt-4 space-y-2 text-xs"><p className="flex justify-between text-slate-400"><span>المشتركون</span><strong className="text-slate-200">{row.subscriber}%</strong></p><p className="flex justify-between text-slate-400"><span>الأفرع</span><strong className="text-slate-200">{row.branch}%</strong></p><p className="flex justify-between text-slate-400"><span>رسائل SMS</span><strong className="text-slate-200">{row.sms}%</strong></p></div></div>)}{!visible.length && <p className="md:col-span-2 xl:col-span-3 rounded-xl border border-dashed border-white/10 py-8 text-center text-sm text-slate-500">لا توجد نتائج مطابقة للفلتر المحدد.</p>}</div></CardContent></Card>;
}

